package it.comune.trieste.ouf.udp;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.sql.Types;
import java.time.OffsetDateTime;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;

@Service
public class HandoffIntakeService {
  @Value("${ouf.udp.execution.enabled:false}") private boolean executionEnabled;
  @org.springframework.beans.factory.annotation.Autowired private LakeCatalogRepository lakeCatalog;
  private final JdbcClient db;private final ObjectMapper json;private final FrozenContractValidator contracts;private final LakeLifecycleService lake;private final TransactionTemplate transactions;private final boolean lakeRequired;private final int rawRetentionDays;private final String rawRetentionClass;private final String rawAccessLabel;private final String tenantId;
  public HandoffIntakeService(JdbcClient db,ObjectMapper json,FrozenContractValidator contracts,LakeLifecycleService lake,TransactionTemplate transactions,@Value("${ouf.udp.lake.required:true}") boolean lakeRequired,@Value("${ouf.udp.lake.raw-retention-days:0}") int rawRetentionDays,@Value("${ouf.udp.lake.raw-retention-class:}") String rawRetentionClass,@Value("${ouf.udp.lake.raw-access-label:}") String rawAccessLabel,@Value("${ouf.udp.lake.tenant-id:}") String tenantId){this.db=db;this.json=json;this.contracts=contracts;this.lake=lake;this.transactions=transactions;this.lakeRequired=lakeRequired;this.rawRetentionDays=rawRetentionDays;this.rawRetentionClass=rawRetentionClass;this.rawAccessLabel=rawAccessLabel;this.tenantId=tenantId;}
  public Receipt accept(Map<String,Object> payload){
    contracts.validate("/contracts/rc3/ingestion/handoff-payload-v1.json",payload);String id=text(payload,"handoffId"),hash=text(payload,"contentHash");Map<String,Object> identity=object(payload,"sourceIdentity");String receipt="udp://handoffs/"+id;List<Map<String,Object>> prior=db.sql("select content_hash,receipt_ref,payload_json=cast(:payload as jsonb) payload_matches from ouf_udp.handoff_intake where handoff_id=:h").param("h",id).param("payload",write(payload)).query().listOfRows();if(!prior.isEmpty())return duplicate(hash,prior.getFirst());String encoded=write(payload);UUID sourceRaw=executionEnabled?verifySourceRaw(payload,identity):null;UUID rawLakeObject=null;if(lakeRequired){if(rawRetentionDays<=0||rawRetentionClass.isBlank()||rawAccessLabel.isBlank()||tenantId.isBlank())throw new IllegalStateException("UDP_LAKE_RETENTION_POLICY_REQUIRED");var raw=lake.store(encoded.getBytes(StandardCharsets.UTF_8),tenantId,text(identity,"sourceId"),text(identity,"typeCode"),"RAW","application/json",rawRetentionClass,rawAccessLabel,OffsetDateTime.now().plusDays(rawRetentionDays),String.valueOf(payload.getOrDefault("correlationId",id)));if(!"VERIFIED".equals(raw.state()))throw new IllegalStateException("UDP_LAKE_RAW_NOT_VERIFIED");rawLakeObject=raw.id();}UUID finalRawLakeObject=rawLakeObject;return transactions.execute(status->{if(sourceRaw!=null&&db.sql("select 1 from ouf_udp.lake_object where lake_object_id=:raw and state='VERIFIED' for update").param("raw",sourceRaw).query(Integer.class).optional().isEmpty())throw new IllegalStateException("UDP_RAW_REFERENCE_NOT_VERIFIED");int inserted=db.sql("insert into ouf_udp.handoff_intake(handoff_id,ingestion_run_id,ingestion_id,source_id,type_code,source_object_id,content_hash,payload_json,receipt_ref,raw_lake_object_id) values(:h,:r,:i,:s,:t,:o,:c,cast(:p as jsonb),:x,:lake) on conflict(handoff_id) do nothing").param("h",id).param("r",text(payload,"ingestionRunId")).param("i",text(payload,"ingestionId")).param("s",text(identity,"sourceId")).param("t",text(identity,"typeCode")).param("o",text(identity,"sourceObjectId")).param("c",hash).param("p",encoded).param("x",receipt).param("lake",finalRawLakeObject,Types.OTHER).update();if(inserted==0)return duplicate(hash,db.sql("select content_hash,receipt_ref,payload_json=cast(:payload as jsonb) payload_matches from ouf_udp.handoff_intake where handoff_id=:h").param("h",id).param("payload",write(payload)).query().singleRow());db.sql("insert into ouf_udp.materialization_job(job_id,handoff_id) values(gen_random_uuid(),:h)").param("h",id).update();if(sourceRaw!=null){db.sql("update ouf_udp.handoff_intake set source_raw_lake_object_id=:raw where handoff_id=:h").param("raw",sourceRaw).param("h",id).update();db.sql("update ouf_udp.lake_object set blocking_lineage_refs=blocking_lineage_refs+1,state_version=state_version+1 where lake_object_id=:raw").param("raw",sourceRaw).update();}event(id,"HANDOFF_DURABLE",finalRawLakeObject==null?Map.of("receiptRef",receipt):Map.of("receiptRef",receipt,"rawLakeObjectId",finalRawLakeObject.toString()));return new Receipt(receipt,true,false);});
  }
  public Map<String,Object> handoff(String id){return db.sql("select handoff_id,ingestion_run_id,ingestion_id,source_id,type_code,source_object_id,content_hash,receipt_ref,raw_lake_object_id,state,received_at,processed_at,failure_code from ouf_udp.handoff_intake where handoff_id=:h").param("h",id).query().listOfRows().stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"UDP_HANDOFF_NOT_FOUND"));}
  private UUID verifySourceRaw(Map<String,Object> payload,Map<String,Object> identity){
    String ref=text(payload,"rawObjectRef");if(!ref.startsWith("lake://"))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"UDP_RAW_REFERENCE_REQUIRED");
    UUID id;try{id=UUID.fromString(ref.substring(7));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"UDP_RAW_REFERENCE_INVALID");}
    var raw=lakeCatalog.get(id);
    if(!tenantId.equals(raw.tenant())||!text(identity,"sourceId").equals(raw.source())||!text(identity,"typeCode").equals(raw.type())||!"RAW".equals(raw.tier())||!"VERIFIED".equals(raw.state()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"UDP_RAW_REFERENCE_NOT_VERIFIED");return id;
  }
  private Receipt duplicate(String hash,Map<String,Object> existing){if(!hash.equals(existing.get("content_hash"))||!Boolean.TRUE.equals(existing.get("payload_matches")))throw new ResponseStatusException(HttpStatus.CONFLICT,"UDP_HANDOFF_IDEMPOTENCY_CONFLICT");return new Receipt(String.valueOf(existing.get("receipt_ref")),true,true);}
  private void event(String id,String type,Map<String,Object> detail){db.sql("insert into ouf_udp.handoff_event(event_id,handoff_id,event_type,safe_detail) values(gen_random_uuid(),:h,:t,cast(:d as jsonb))").param("h",id).param("t",type).param("d",write(detail)).update();}
  private String write(Object v){try{return json.writeValueAsString(v);}catch(JsonProcessingException e){throw new IllegalArgumentException("UDP_JSON_INVALID",e);}}
  @SuppressWarnings("unchecked") static Map<String,Object> object(Map<String,Object> map,String key){return (Map<String,Object>)map.get(key);}static String text(Map<String,Object> map,String key){return String.valueOf(map.get(key));}
  public record Receipt(String receiptRef,boolean durable,boolean duplicate){}
}
